#!/usr/bin/env python3
"""Refresh the auto-generated open-followups summary inside docs/followups/index.md."""

from __future__ import annotations

import argparse
import difflib
import hashlib
import json
import re
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path
import sys
from typing import Iterable, Mapping

import followups_lint


AUTO_START = "<!-- AUTO-OPEN-SUMMARY:START -->"
AUTO_END = "<!-- AUTO-OPEN-SUMMARY:END -->"
ACTIVE_STATUSES = {"open", "promoted", "unconfirmed"}
PRIORITY_ORDER = ("P0", "P1", "P2", "P?")
TIMESTAMP_LINE_RE = re.compile(
    r"^_Auto-generated by `scripts/followups_index_rebuild\.py` on (?P<stamp>.+)\._$"
)
TIMESTAMP_PLACEHOLDER = (
    "_Auto-generated by `scripts/followups_index_rebuild.py` on <timestamp>._"
)
BANNER_LINE = (
    "_DO NOT EDIT - regenerate via `PYTHONDONTWRITEBYTECODE=1 "
    "python3 -B scripts/followups_index_rebuild.py --project-root .`._"
)
# Both compatibility rows (``file.md:line``) and V2 rows
# (``source_ref#item_id``) use a backticked first cell.  Counting only the
# legacy line suffix made a green V2 summary report a misleading live-row
# total, even though the normalized content comparison was correct.
SUMMARY_ROW_RE = re.compile(r"^\|\s*`[^`]+`\s*\|")


@dataclass(frozen=True)
class SummaryRow:
    priority: str
    source_ref: str
    summary: str
    assignee: str
    status: str
    plan: str


@dataclass(frozen=True)
class CheckResult:
    ok: bool
    index_path: Path
    expected_rows: int
    live_rows: int | None
    issues: tuple[str, ...]
    timestamp_ignored: bool
    diff: tuple[str, ...]


@dataclass(frozen=True)
class BoundIndexRender:
    """One deterministic generated-index candidate from a bound source map."""

    index_bytes: bytes
    authoritative_followups_manifest_sha256: str
    rendered_summary_sha256: str
    expected_rows: int


class BoundIndexInputError(ValueError):
    """Raised when the terminal owner supplies an unsafe bound input set."""


def resolve_project_root(raw: str | None) -> Path:
    root = Path(raw).expanduser() if raw else Path.cwd()
    return root.resolve()


def should_include_file(file_obj: followups_lint.FollowupFile) -> bool:
    if file_obj.is_master:
        return True
    if file_obj.imported_refs:
        return False
    if file_obj.is_done and all(
        (item.status or "").lower() not in ACTIVE_STATUSES for item in file_obj.items
    ):
        return False
    return True


def collect_rows(project_root: Path) -> list[SummaryRow]:
    rows: list[SummaryRow] = []
    target_cache: dict[str, followups_lint.TargetState] = {}
    for file_obj in followups_lint.load_followup_files(project_root):
        if not should_include_file(file_obj):
            continue
        for item in file_obj.items:
            status = (item.status or "").lower()
            if status not in ACTIVE_STATUSES:
                continue
            if status == "promoted":
                state = followups_lint.resolve_target_state(project_root, item.plan, target_cache)
                if state.bucket == "done_plan":
                    continue
            # V2 row identity survives a carrier rename and any line movement.
            # Keep the legacy file:line display only for V1 compatibility.
            if followups_lint.is_v2_followup(file_obj) and item.source_ref and item.item_id:
                source_identity = f"{item.source_ref}#{item.item_id}"
            else:
                source_identity = f"{item.rel_path}:{item.line_no}"
            rows.append(
                SummaryRow(
                    priority=item.priority,
                    source_ref=source_identity,
                    summary=item.summary,
                    assignee=item.assignee or "UNCONFIRMED",
                    status=status,
                    plan=item.plan or "null",
                )
            )
    return rows


def _sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _canonical_json(value: object) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")


def _validate_bound_source_path(raw_path: object) -> str:
    if not isinstance(raw_path, str):
        raise BoundIndexInputError("bound follow-ups source path must be a string")
    try:
        from followups_capture import validate_followup_relpath
    except ModuleNotFoundError:  # package import in focused unittest invocation
        from scripts.followups_capture import validate_followup_relpath
    try:
        rel_path = validate_followup_relpath(raw_path)
    except Exception as exc:
        raise BoundIndexInputError(f"bound follow-ups source path is unsafe: {raw_path!r}") from exc
    if rel_path != raw_path or Path(rel_path).name in followups_lint.FOLLOWUPS_IGNORE:
        raise BoundIndexInputError(f"bound follow-ups source path is ignored or non-canonical: {raw_path!r}")
    return rel_path


def authoritative_followups_manifest(source_bytes: Mapping[str, bytes]) -> dict[str, dict[str, object]]:
    """Return the canonical raw-followups manifest for one already-bound byte map.

    The map deliberately excludes generated and compatibility-only ignored files.
    Callers must preserve sorted paths, so a missing or reordered source cannot be
    silently substituted with a later ambient filesystem read.
    """

    if not isinstance(source_bytes, Mapping):
        raise BoundIndexInputError("bound follow-ups source map must be a mapping")
    paths = list(source_bytes)
    if paths != sorted(paths) or len(paths) != len(set(paths)):
        raise BoundIndexInputError("bound follow-ups source paths must be sorted and unique")
    manifest: dict[str, dict[str, object]] = {}
    for raw_path in paths:
        rel_path = _validate_bound_source_path(raw_path)
        data = source_bytes[raw_path]
        if not isinstance(data, bytes):
            raise BoundIndexInputError(f"bound follow-ups source is not bytes: {rel_path}")
        manifest[rel_path] = {"sha256": _sha256(data), "st_size": len(data)}
    return manifest


def _validate_bound_manifest(
    source_bytes: Mapping[str, bytes],
    source_manifest: Mapping[str, object],
) -> dict[str, dict[str, object]]:
    expected = authoritative_followups_manifest(source_bytes)
    if not isinstance(source_manifest, Mapping):
        raise BoundIndexInputError("bound follow-ups manifest must be a mapping")
    if list(source_manifest) != sorted(source_manifest) or set(source_manifest) != set(expected):
        raise BoundIndexInputError("bound follow-ups manifest paths differ from bound source bytes")
    normalized: dict[str, dict[str, object]] = {}
    for path in sorted(expected):
        value = source_manifest[path]
        if not isinstance(value, Mapping) or set(value) != {"sha256", "st_size"}:
            raise BoundIndexInputError(f"bound follow-ups manifest object is invalid: {path}")
        digest = value.get("sha256")
        size = value.get("st_size")
        if not isinstance(digest, str) or not re.fullmatch(r"[0-9a-f]{64}", digest):
            raise BoundIndexInputError(f"bound follow-ups manifest hash is invalid: {path}")
        if not isinstance(size, int) or isinstance(size, bool) or size < 0:
            raise BoundIndexInputError(f"bound follow-ups manifest size is invalid: {path}")
        normalized[path] = {"sha256": digest, "st_size": size}
    if normalized != expected:
        raise BoundIndexInputError("bound follow-ups manifest does not match bound source bytes")
    return normalized


def _bound_promoted_plan_key(plan_value: str | None) -> str:
    """Return the canonical lifecycle key for one rendered promoted row."""

    normalized = followups_lint.normalize_plan_value(plan_value)
    return normalized if normalized is not None else "null"


def _bound_promoted_plan_keys(
    project_root: Path,
    source_bytes: Mapping[str, bytes],
    source_manifest: Mapping[str, object],
) -> tuple[str, ...]:
    """Discover only lifecycle inputs that can affect the rendered summary."""

    _validate_bound_manifest(source_bytes, source_manifest)
    keys: set[str] = set()
    for rel_path in sorted(source_bytes):
        try:
            text = source_bytes[rel_path].decode("utf-8")
        except UnicodeDecodeError as exc:
            raise BoundIndexInputError(f"bound follow-ups source is not UTF-8: {rel_path}") from exc
        file_obj = followups_lint.parse_followup_text(text, rel_path, project_root / rel_path)
        if not should_include_file(file_obj):
            continue
        for item in file_obj.items:
            if (item.status or "").lower() == "promoted":
                keys.add(_bound_promoted_plan_key(item.plan))
    return tuple(sorted(keys))


def promoted_plan_lifecycle_manifest(
    project_root: Path,
    source_bytes: Mapping[str, bytes],
    source_manifest: Mapping[str, object],
) -> dict[str, dict[str, object]]:
    """Bind the live lifecycle objects that affect promoted-row visibility.

    This is intentionally a live-source adapter, not part of the pure renderer.
    The returned map captures both the legacy target-state bucket and the exact
    current target object digest, so a terminal transaction can authenticate the
    lifecycle basis through its existing receipt digest without a new receipt
    field or manifest profile.
    """

    manifest = _validate_bound_manifest(source_bytes, source_manifest)
    target_cache: dict[str, followups_lint.TargetState] = {}
    lifecycle: dict[str, dict[str, object]] = {}
    for plan_key in _bound_promoted_plan_keys(project_root, source_bytes, manifest):
        plan_value = None if plan_key == "null" else plan_key
        state = followups_lint.resolve_target_state(project_root, plan_value, target_cache)
        object_sha256: str | None = None
        if state.exists:
            if state.resolved_path is None:
                raise BoundIndexInputError(f"promoted lifecycle path is unavailable: {plan_key}")
            try:
                before = state.resolved_path.read_bytes()
                after = state.resolved_path.read_bytes()
            except OSError as exc:
                raise BoundIndexInputError(f"cannot bind promoted lifecycle object: {plan_key}") from exc
            if before != after:
                raise BoundIndexInputError(f"promoted lifecycle object drifted while reading: {plan_key}")
            object_sha256 = _sha256(before)
        lifecycle[plan_key] = {
            "bucket": state.bucket,
            "exists": state.exists,
            "kind": state.kind,
            "object_sha256": object_sha256,
            "status": state.status_norm,
        }
    return lifecycle


def _validate_bound_promoted_plan_lifecycle(
    project_root: Path,
    source_bytes: Mapping[str, bytes],
    source_manifest: Mapping[str, object],
    lifecycle_manifest: Mapping[str, object],
) -> dict[str, dict[str, object]]:
    """Validate caller-bound promoted lifecycle input without ambient reads."""

    if not isinstance(lifecycle_manifest, Mapping):
        raise BoundIndexInputError("bound promoted lifecycle manifest must be a mapping")
    expected_keys = _bound_promoted_plan_keys(project_root, source_bytes, source_manifest)
    if list(lifecycle_manifest) != list(expected_keys) or set(lifecycle_manifest) != set(expected_keys):
        raise BoundIndexInputError("bound promoted lifecycle paths differ from bound source bytes")
    normalized: dict[str, dict[str, object]] = {}
    required = {"bucket", "exists", "kind", "object_sha256", "status"}
    for plan_key in expected_keys:
        value = lifecycle_manifest[plan_key]
        if not isinstance(value, Mapping) or set(value) != required:
            raise BoundIndexInputError(f"bound promoted lifecycle object is invalid: {plan_key}")
        bucket = value.get("bucket")
        exists = value.get("exists")
        kind = value.get("kind")
        object_sha256 = value.get("object_sha256")
        status = value.get("status")
        if not isinstance(bucket, str) or not bucket:
            raise BoundIndexInputError(f"bound promoted lifecycle bucket is invalid: {plan_key}")
        if not isinstance(exists, bool):
            raise BoundIndexInputError(f"bound promoted lifecycle exists flag is invalid: {plan_key}")
        if not isinstance(kind, str) or not kind:
            raise BoundIndexInputError(f"bound promoted lifecycle kind is invalid: {plan_key}")
        if status is not None and not isinstance(status, str):
            raise BoundIndexInputError(f"bound promoted lifecycle status is invalid: {plan_key}")
        if exists:
            if not isinstance(object_sha256, str) or not re.fullmatch(r"[0-9a-f]{64}", object_sha256):
                raise BoundIndexInputError(f"bound promoted lifecycle hash is invalid: {plan_key}")
        elif object_sha256 is not None:
            raise BoundIndexInputError(f"missing promoted lifecycle object has a hash: {plan_key}")
        normalized[plan_key] = {
            "bucket": bucket,
            "exists": exists,
            "kind": kind,
            "object_sha256": object_sha256,
            "status": status,
        }
    return normalized


def _bound_render_input_sha256(
    raw_manifest: Mapping[str, object],
    lifecycle_manifest: Mapping[str, object],
) -> str:
    """Hash the complete renderer input under the existing receipt field."""

    return _sha256(
        _canonical_json(
            {
                "raw_followups_manifest": raw_manifest,
                "promoted_plan_lifecycle": lifecycle_manifest,
            }
        )
    )


def collect_rows_from_bound_bytes(
    project_root: Path,
    source_bytes: Mapping[str, bytes],
    source_manifest: Mapping[str, object],
    *,
    promoted_plan_lifecycle: Mapping[str, object],
) -> list[SummaryRow]:
    """Collect rows from exact source and lifecycle maps without ambient reads."""

    manifest = _validate_bound_manifest(source_bytes, source_manifest)
    lifecycle = _validate_bound_promoted_plan_lifecycle(
        project_root,
        source_bytes,
        manifest,
        promoted_plan_lifecycle,
    )
    rows: list[SummaryRow] = []
    for rel_path in sorted(source_bytes):
        try:
            text = source_bytes[rel_path].decode("utf-8")
        except UnicodeDecodeError as exc:
            raise BoundIndexInputError(f"bound follow-ups source is not UTF-8: {rel_path}") from exc
        file_obj = followups_lint.parse_followup_text(text, rel_path, project_root / rel_path)
        if not should_include_file(file_obj):
            continue
        for item in file_obj.items:
            status = (item.status or "").lower()
            if status not in ACTIVE_STATUSES:
                continue
            if status == "promoted":
                if lifecycle[_bound_promoted_plan_key(item.plan)]["bucket"] == "done_plan":
                    continue
            if followups_lint.is_v2_followup(file_obj) and item.source_ref and item.item_id:
                source_identity = f"{item.source_ref}#{item.item_id}"
            else:
                source_identity = f"{item.rel_path}:{item.line_no}"
            rows.append(
                SummaryRow(
                    priority=item.priority,
                    source_ref=source_identity,
                    summary=item.summary,
                    assignee=item.assignee or "UNCONFIRMED",
                    status=status,
                    plan=item.plan or "null",
                )
            )
    return rows


def render_bound_index(
    project_root: Path,
    source_bytes: Mapping[str, bytes],
    source_manifest: Mapping[str, object],
    index_before_bytes: bytes,
    *,
    promoted_plan_lifecycle: Mapping[str, object],
    stamp: str | None = None,
) -> BoundIndexRender:
    """Build one index candidate from caller-bound raw bytes and index before-image.

    This intentionally has no source-file reads.  Promoted-plan lifecycle
    visibility is an explicit caller-bound input, so receipt/readback cannot
    silently substitute a later ambient target-plan status.
    """

    manifest = _validate_bound_manifest(source_bytes, source_manifest)
    if not isinstance(index_before_bytes, bytes):
        raise BoundIndexInputError("bound index before-image must be bytes")
    try:
        index_text = index_before_bytes.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise BoundIndexInputError("bound index before-image is not UTF-8") from exc
    lifecycle = _validate_bound_promoted_plan_lifecycle(
        project_root,
        source_bytes,
        manifest,
        promoted_plan_lifecycle,
    )
    rows = collect_rows_from_bound_bytes(
        project_root,
        source_bytes,
        manifest,
        promoted_plan_lifecycle=lifecycle,
    )
    summary = render_summary(rows, stamp=stamp)
    updated = replace_auto_block(index_text, build_auto_block(summary)).encode("utf-8")
    return BoundIndexRender(
        index_bytes=updated,
        authoritative_followups_manifest_sha256=_bound_render_input_sha256(manifest, lifecycle),
        rendered_summary_sha256=_sha256(summary.encode("utf-8")),
        expected_rows=len(rows),
    )


def render_summary(rows: Iterable[SummaryRow], *, stamp: str | None = None) -> str:
    grouped: dict[str, list[SummaryRow]] = {prio: [] for prio in PRIORITY_ORDER}
    for row in rows:
        grouped.setdefault(row.priority, []).append(row)

    if stamp is None:
        stamp = datetime.now().astimezone().strftime("%Y-%m-%d %H:%M %z")
    lines = [
        "## Open follow-ups summary (auto)",
        f"_Auto-generated by `scripts/followups_index_rebuild.py` on {stamp}._",
        BANNER_LINE,
        "",
    ]
    for priority in PRIORITY_ORDER:
        items = grouped.get(priority, [])
        lines.append(f"### {priority} ({len(items)} open)")
        if not items:
            lines.append("- none")
            lines.append("")
            continue
        lines.append("| Source | Topic | To | Status | Plan |")
        lines.append("| --- | --- | --- | --- | --- |")
        for item in items:
            summary = item.summary.replace("|", "\\|")
            plan = item.plan.replace("|", "\\|")
            lines.append(
                f"| `{item.source_ref}` | {summary} | `{item.assignee}` | `{item.status}` | `{plan}` |"
            )
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def followups_index_path(project_root: Path) -> Path:
    return project_root / "docs" / "followups" / "index.md"


def build_auto_block(summary: str) -> str:
    return f"{AUTO_START}\n{summary}{AUTO_END}"


def replace_auto_block(text: str, block: str) -> str:
    if AUTO_START in text and AUTO_END in text:
        start = text.index(AUTO_START)
        end = text.index(AUTO_END) + len(AUTO_END)
        return text[:start].rstrip() + "\n\n" + block + "\n"
    return text.rstrip() + "\n\n" + block + "\n"


def rebuild_index(project_root: Path, *, stamp: str | None = None) -> Path:
    index_path = followups_index_path(project_root)
    if not index_path.exists():
        raise FileNotFoundError(index_path)

    try:
        from followups_capture import read_followup_path, snapshot_followups
    except ModuleNotFoundError:  # package import in focused unittest invocation
        from scripts.followups_capture import read_followup_path, snapshot_followups
    _objects, contents = snapshot_followups(project_root, include_bytes=True)
    source_bytes = {
        path: contents[path]
        for path in sorted(contents)
        if Path(path).name not in followups_lint.FOLLOWUPS_IGNORE
    }
    source_manifest = authoritative_followups_manifest(source_bytes)
    _index_object, index_before = read_followup_path(project_root, "docs/followups/index.md")
    rendered = render_bound_index(
        project_root,
        source_bytes,
        source_manifest,
        index_before,
        promoted_plan_lifecycle=promoted_plan_lifecycle_manifest(
            project_root,
            source_bytes,
            source_manifest,
        ),
        stamp=stamp,
    )
    index_path.write_bytes(rendered.index_bytes)
    return index_path


def extract_auto_summary(text: str) -> tuple[str | None, tuple[str, ...]]:
    start_count = text.count(AUTO_START)
    end_count = text.count(AUTO_END)
    if start_count == 0 or end_count == 0:
        return None, ("missing_generated_block",)
    if start_count != 1 or end_count != 1:
        return None, ("multiple_generated_blocks",)

    start = text.index(AUTO_START) + len(AUTO_START)
    end = text.index(AUTO_END)
    if end <= start:
        return None, ("malformed_generated_block",)

    summary = text[start:end]
    if summary.startswith("\n"):
        summary = summary[1:]
    return summary, ()


def normalize_generated_summary(summary: str) -> tuple[str, bool]:
    timestamp_seen = False
    lines: list[str] = []
    for line in summary.splitlines():
        if TIMESTAMP_LINE_RE.match(line):
            lines.append(TIMESTAMP_PLACEHOLDER)
            timestamp_seen = True
        else:
            lines.append(line)
    return "\n".join(lines).rstrip() + "\n", timestamp_seen


def generated_summary_stamp(index_bytes: bytes) -> str | None:
    """Return the existing generated timestamp without treating it as authority."""

    try:
        text = index_bytes.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise BoundIndexInputError("bound index before-image is not UTF-8") from exc
    summary, issues = extract_auto_summary(text)
    if issues or summary is None:
        return None
    for line in summary.splitlines():
        match = TIMESTAMP_LINE_RE.match(line)
        if match:
            return match.group("stamp")
    return None


def count_rendered_rows(summary: str) -> int:
    return sum(1 for line in summary.splitlines() if SUMMARY_ROW_RE.match(line))


def check_index(project_root: Path) -> CheckResult:
    index_path = followups_index_path(project_root)
    if not index_path.exists():
        raise FileNotFoundError(index_path)

    expected_source_rows = collect_rows(project_root)
    expected_summary = render_summary(expected_source_rows)
    text = index_path.read_text(encoding="utf-8")
    live_summary, marker_issues = extract_auto_summary(text)
    if marker_issues:
        return CheckResult(
            ok=False,
            index_path=index_path,
            expected_rows=len(expected_source_rows),
            live_rows=None,
            issues=marker_issues,
            timestamp_ignored=False,
            diff=(),
        )
    assert live_summary is not None

    expected_normalized, _ = normalize_generated_summary(expected_summary)
    live_normalized, live_timestamp_seen = normalize_generated_summary(live_summary)

    issues: list[str] = []
    if not live_timestamp_seen:
        issues.append("missing_timestamp_line")
    if BANNER_LINE not in live_summary.splitlines():
        issues.append("missing_banner_line")
    diff: tuple[str, ...] = ()
    if expected_normalized != live_normalized:
        issues.append("generated_content_mismatch")
        diff = tuple(
            difflib.unified_diff(
                expected_normalized.splitlines(),
                live_normalized.splitlines(),
                fromfile="expected",
                tofile="live",
                lineterm="",
            )
        )

    return CheckResult(
        ok=not issues,
        index_path=index_path,
        expected_rows=len(expected_source_rows),
        live_rows=count_rendered_rows(live_summary),
        issues=tuple(issues),
        timestamp_ignored=live_timestamp_seen,
        diff=diff,
    )


def result_payload(result: CheckResult, project_root: Path) -> dict[str, object]:
    rel_path = result.index_path.relative_to(project_root).as_posix()
    return {
        "status": "ok" if result.ok else "failed",
        "ok": result.ok,
        "index_path": rel_path,
        "expected_rows": result.expected_rows,
        "live_rows": result.live_rows,
        "timestamp_ignored": result.timestamp_ignored,
        "issues": list(result.issues),
        "diff": list(result.diff),
        "would_write": False,
    }


def render_check_result(result: CheckResult, project_root: Path) -> str:
    payload = result_payload(result, project_root)
    rel_path = payload["index_path"]
    if result.ok:
        return (
            f"OK: {rel_path} matches generated follow-ups summary "
            f"(rows={result.expected_rows}; timestamp ignored; no write)."
        )

    lines = [
        f"FAILED: {rel_path} generated follow-ups summary is stale or missing.",
        f"expected_rows={result.expected_rows}",
        f"live_rows={result.live_rows if result.live_rows is not None else 'unknown'}",
    ]
    for issue in result.issues:
        lines.append(f"issue={issue}")
    if result.diff:
        lines.append("diff:")
        lines.extend(result.diff[:80])
    return "\n".join(lines)


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Rebuild the auto-generated open-followups summary in docs/followups/index.md."
    )
    parser.add_argument(
        "--project-root",
        default="",
        help="Repo root owning docs/followups (default: cwd).",
    )
    parser.add_argument(
        "--check",
        action="store_true",
        help="Check the generated summary without writing docs/followups/index.md.",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="With --check, emit a machine-readable parity report.",
    )
    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    if args.json and not args.check:
        parser.error("--json requires --check")
    root = resolve_project_root(args.project_root)
    if args.check:
        try:
            result = check_index(root)
        except FileNotFoundError as exc:
            if args.json:
                print(
                    json.dumps(
                        {
                            "status": "failed",
                            "ok": False,
                            "index_path": str(exc),
                            "expected_rows": None,
                            "live_rows": None,
                            "timestamp_ignored": False,
                            "issues": ["missing_followups_index"],
                            "diff": [],
                            "would_write": False,
                        },
                        ensure_ascii=False,
                        sort_keys=True,
                    )
                )
            else:
                print(f"Missing followups index: {exc}", file=sys.stderr)
            return 1
        if args.json:
            print(json.dumps(result_payload(result, root), ensure_ascii=False, sort_keys=True))
        else:
            stream = sys.stdout if result.ok else sys.stderr
            print(render_check_result(result, root), file=stream)
        return 0 if result.ok else 1

    try:
        index_path = rebuild_index(root)
    except FileNotFoundError as exc:
        print(f"Missing followups index: {exc}", file=sys.stderr)
        return 1
    print(index_path.relative_to(root).as_posix())
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
